import { mapStatusToDefaultCode, TableServiceError } from './errors';
import type {
  DatasetResponse,
  DatasetDiscoveryResponse,
  DeleteRowResponse,
  EnvelopeFailure,
  EnvelopeSuccess,
  InsertRowRequest,
  ImportRowsRequest,
  ImportRowsResponse,
  LayoutResponse,
  MoveRowsRequest,
  MoveRowsResponse,
  PatchRowRequest,
  QueryRowsRequest,
  QueryRowsResponse,
  CanonicalRow,
  RowDetailResponse,
  AttachRowFileRequest,
  AttachRowFileResponse,
  TableClientConfig,
  TriggerSyncResponse,
  PatchMetadataRequest,
  MetadataResponse,
  PurgeColumnsRequest,
  PurgeColumnsResponse,
  RowIterationOptions,
  TableColumns,
  TableRowMutationContext,
} from './types';

export const TABLE_CLIENT_LIMITS = {
  defaultMaxResponseBytes: 2 * 1024 * 1024,
  hardMaxResponseBytes: 10 * 1024 * 1024,
  defaultMaxPageSize: 100,
  hardMaxPageSize: 200,
  defaultMaxPages: 20,
  hardMaxPages: 100,
  defaultMaxRows: 1_000,
  hardMaxRows: 10_000,
} as const;

export class TableClient {
  private readonly baseUrl: string;
  private readonly getToken: TableClientConfig['getToken'];
  private readonly fetchImpl: typeof fetch;
  private readonly timeoutMs: number;
  private readonly maxResponseBytes: number;
  private readonly maxPageSize: number;

  constructor(config: TableClientConfig) {
    this.baseUrl = normalizeBaseUrl(config.baseUrl);
    this.getToken = config.getToken;
    this.fetchImpl = config.fetch ?? fetch;
    this.timeoutMs = boundedInteger(
      config.timeoutMs ?? 25_000,
      1,
      300_000,
      'timeoutMs',
    );
    this.maxResponseBytes = boundedInteger(
      config.maxResponseBytes ?? TABLE_CLIENT_LIMITS.defaultMaxResponseBytes,
      1,
      TABLE_CLIENT_LIMITS.hardMaxResponseBytes,
      'maxResponseBytes',
    );
    this.maxPageSize = boundedInteger(
      config.maxPageSize ?? TABLE_CLIENT_LIMITS.defaultMaxPageSize,
      1,
      TABLE_CLIENT_LIMITS.hardMaxPageSize,
      'maxPageSize',
    );
  }

  listDatasets(): Promise<DatasetDiscoveryResponse> {
    return this.request('GET', '/api/v2/tables');
  }

  getDataset(datasetId: string): Promise<DatasetResponse> {
    return this.request(
      'GET',
      `/api/v2/tables/${encodeURIComponent(datasetId)}`,
    );
  }

  getLayout<TColumns extends TableColumns = TableColumns>(
    datasetId: string,
    options?: {
      viewId?: string;
      filter?: Record<string, unknown>;
      includeArchived?: boolean;
    },
  ): Promise<LayoutResponse<TColumns>> {
    const params = new URLSearchParams();
    if (options?.viewId) params.set('viewId', options.viewId);
    if (options?.filter) params.set('filter', JSON.stringify(options.filter));
    if (options?.includeArchived) params.set('includeArchived', 'true');
    const qs = params.toString();
    const path = `/api/v2/tables/${encodeURIComponent(datasetId)}/layout${qs ? `?${qs}` : ''}`;
    return this.request('GET', path);
  }

  queryRows<TColumns extends TableColumns = TableColumns>(
    datasetId: string,
    body: QueryRowsRequest,
  ): Promise<QueryRowsResponse<TColumns>> {
    const boundedBody = {
      ...body,
      ...(body.limit === undefined
        ? {}
        : {
            limit: Math.min(
              positiveInteger(body.limit, 'limit'),
              this.maxPageSize,
            ),
          }),
    };
    return this.request(
      'POST',
      `/api/v2/tables/${encodeURIComponent(datasetId)}/rows/query`,
      boundedBody,
    );
  }

  async *iterateRows<TColumns extends TableColumns = TableColumns>(
    datasetId: string,
    query: Omit<QueryRowsRequest, 'cursor' | 'limit'> & {
      cursor?: string;
      limit?: number;
    } = {},
    options: RowIterationOptions = {},
  ): AsyncGenerator<CanonicalRow<TColumns>, void, undefined> {
    const maxPages = boundedInteger(
      options.maxPages ?? TABLE_CLIENT_LIMITS.defaultMaxPages,
      1,
      TABLE_CLIENT_LIMITS.hardMaxPages,
      'maxPages',
    );
    const maxRows = boundedInteger(
      options.maxRows ?? TABLE_CLIENT_LIMITS.defaultMaxRows,
      1,
      TABLE_CLIENT_LIMITS.hardMaxRows,
      'maxRows',
    );
    const pageSize = Math.min(
      positiveInteger(
        options.pageSize ??
          query.limit ??
          TABLE_CLIENT_LIMITS.defaultMaxPageSize,
        'pageSize',
      ),
      this.maxPageSize,
      maxRows,
    );
    let cursor = query.cursor?.trim() || undefined;
    let yielded = 0;
    const seenCursors = new Set<string>(cursor ? [cursor] : []);

    for (
      let pageNumber = 0;
      pageNumber < maxPages && yielded < maxRows;
      pageNumber += 1
    ) {
      const page = await this.queryRows<TColumns>(datasetId, {
        ...query,
        cursor,
        limit: Math.min(pageSize, maxRows - yielded),
      });
      if (!Array.isArray(page.rows)) {
        throw invalidResponse('Table query response is missing rows');
      }
      for (const row of page.rows) {
        if (yielded >= maxRows) return;
        yielded += 1;
        yield row;
      }
      const nextCursor = page.nextCursor?.trim();
      if (!nextCursor) return;
      if (nextCursor === cursor || seenCursors.has(nextCursor)) {
        throw invalidResponse('Table query returned a repeated cursor');
      }
      seenCursors.add(nextCursor);
      cursor = nextCursor;
    }
  }

  insertRow<TColumns extends TableColumns = TableColumns>(
    datasetId: string,
    body: InsertRowRequest,
    context?: TableRowMutationContext,
  ): Promise<CanonicalRow<TColumns>> {
    return this.request(
      'POST',
      `/api/v2/tables/${encodeURIComponent(datasetId)}/rows`,
      body,
      mutationHeaders(context),
    );
  }

  importRows(
    datasetId: string,
    body: ImportRowsRequest,
  ): Promise<ImportRowsResponse> {
    return this.request(
      'POST',
      `/api/v2/tables/${encodeURIComponent(datasetId)}/rows/import`,
      body,
    );
  }

  patchRow<TColumns extends TableColumns = TableColumns>(
    datasetId: string,
    rowId: string,
    body: PatchRowRequest,
    context?: TableRowMutationContext,
  ): Promise<CanonicalRow<TColumns>> {
    return this.request(
      'PATCH',
      `/api/v2/tables/${encodeURIComponent(datasetId)}/rows/${encodeURIComponent(rowId)}`,
      body,
      mutationHeaders(context),
    );
  }

  getRow<TColumns extends TableColumns = TableColumns>(
    datasetId: string,
    rowId: string,
  ): Promise<RowDetailResponse<TColumns>> {
    return this.request(
      'GET',
      `/api/v2/tables/${encodeURIComponent(datasetId)}/rows/${encodeURIComponent(rowId)}`,
    );
  }

  moveRows(
    datasetId: string,
    body: MoveRowsRequest,
    context?: TableRowMutationContext,
  ): Promise<MoveRowsResponse> {
    return this.request(
      'PATCH',
      `/api/v2/tables/${encodeURIComponent(datasetId)}/rows/move`,
      body,
      mutationHeaders(context),
    );
  }

  deleteRow(
    datasetId: string,
    rowId: string,
    context?: TableRowMutationContext,
  ): Promise<DeleteRowResponse> {
    return this.request(
      'DELETE',
      `/api/v2/tables/${encodeURIComponent(datasetId)}/rows/${encodeURIComponent(rowId)}`,
      undefined,
      mutationHeaders(context),
    );
  }

  triggerSync(datasetId: string): Promise<TriggerSyncResponse> {
    return this.request(
      'POST',
      `/api/v2/tables/${encodeURIComponent(datasetId)}/sync`,
    );
  }

  patchMetadata(
    datasetId: string,
    body: PatchMetadataRequest,
  ): Promise<MetadataResponse> {
    return this.request(
      'PATCH',
      `/api/v2/tables/${encodeURIComponent(datasetId)}/metadata`,
      body,
    );
  }

  attachRowFile(
    datasetId: string,
    rowId: string,
    body: AttachRowFileRequest,
  ): Promise<AttachRowFileResponse> {
    return this.request(
      'POST',
      `/api/v2/tables/${encodeURIComponent(datasetId)}/rows/${encodeURIComponent(rowId)}/files`,
      body,
    );
  }

  purgeColumns(
    datasetId: string,
    body: PurgeColumnsRequest,
  ): Promise<PurgeColumnsResponse> {
    return this.request(
      'POST',
      `/api/v2/tables/${encodeURIComponent(datasetId)}/metadata/purge-columns`,
      body,
    );
  }

  private async request<T>(
    method: string,
    path: string,
    body?: unknown,
    additionalHeaders: Record<string, string> = {},
  ): Promise<T> {
    try {
      const providedToken = await this.getToken();
      if (typeof providedToken !== 'string' || !providedToken.trim()) {
        throw new TableServiceError({
          code: 'UNAUTHORIZED',
          message: 'Table credential provider returned an empty token',
          statusCode: 401,
          requestId: '',
        });
      }
      const token = providedToken.trim();
      const headers: Record<string, string> = {
        Authorization: `Bearer ${token}`,
        Accept: 'application/json',
        ...additionalHeaders,
      };
      const init: RequestInit = {
        method,
        headers,
        signal: AbortSignal.timeout(this.timeoutMs),
      };
      if (body !== undefined) {
        headers['Content-Type'] = 'application/json';
        init.body = JSON.stringify(body);
      }

      const response = await this.fetchImpl(
        `${this.baseUrl}${path}`,
        init,
      ).catch((error: unknown) => {
        const name = error instanceof Error ? error.name : '';
        if (name === 'TimeoutError' || name === 'AbortError') {
          throw new TableServiceError({
            code: 'SOURCE_TIMEOUT',
            message: 'Table service request timed out',
            statusCode: 504,
            requestId: '',
          });
        }
        const message =
          error instanceof Error ? error.message : 'Table edge request failed';
        throw new TableServiceError({
          code: 'INTERNAL_ERROR',
          message,
          statusCode: 502,
          requestId: '',
        });
      });
      const text = await readBoundedResponse(response, this.maxResponseBytes);
      let parsedPayload: unknown;
      try {
        parsedPayload = JSON.parse(text);
      } catch {
        if (response.ok) {
          throw invalidResponse(
            'Table service returned a success response that is not valid JSON',
          );
        }
        throw new TableServiceError({
          code: mapStatusToDefaultCode(response.status),
          message:
            text.trim() ||
            response.statusText ||
            'Unexpected response from table service',
          statusCode: response.status,
          requestId: '',
        });
      }
      if (!isRecord(parsedPayload)) {
        if (response.ok) {
          throw invalidResponse(
            'Table service returned a malformed success envelope',
          );
        }
        throw new TableServiceError({
          code: mapStatusToDefaultCode(response.status),
          message:
            response.statusText || 'Unexpected response from table service',
          statusCode: response.status,
          requestId: '',
        });
      }
      const payload = parsedPayload as EnvelopeSuccess<T> | EnvelopeFailure;

      if (!response.ok || payload.status === 'Failure') {
        const failure = payload as EnvelopeFailure;
        throw new TableServiceError({
          code: failure.error?.code ?? mapStatusToDefaultCode(response.status),
          message: failure.error?.message ?? response.statusText,
          statusCode: response.status,
          requestId: failure.requestId ?? '',
          correlationURL: failure.error?.correlationURL,
        });
      }

      if (payload.status !== 'Success' || !('data' in payload)) {
        throw invalidResponse(
          'Table service returned a malformed success envelope',
        );
      }
      return (payload as EnvelopeSuccess<T>).data;
    } catch (error) {
      if (error instanceof TableServiceError) {
        throw error;
      }
      const message =
        error instanceof Error ? error.message : 'Table edge request failed';
      throw new TableServiceError({
        code: 'INTERNAL_ERROR',
        message,
        statusCode: 502,
        requestId: '',
      });
    }
  }
}

function mutationHeaders(
  context: TableRowMutationContext | undefined,
): Record<string, string> {
  if (!context) return {};

  const origin = context.origin?.trim();
  const commandId = context.commandId?.trim();
  return {
    ...(origin ? { 'X-Process-Table-Origin': origin } : {}),
    ...(commandId ? { 'X-Process-Table-Command-Id': commandId } : {}),
  };
}

function normalizeBaseUrl(baseUrl: string): string {
  const normalized = baseUrl.trim().replace(/\/+$/, '');
  let parsed: URL;
  try {
    parsed = new URL(normalized);
  } catch {
    throw new TypeError('baseUrl must be an absolute HTTP(S) URL');
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    throw new TypeError('baseUrl must use http or https');
  }
  return normalized;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function positiveInteger(value: number, name: string): number {
  if (!Number.isInteger(value) || value <= 0) {
    throw new TypeError(`${name} must be a positive integer`);
  }
  return value;
}

function boundedInteger(
  value: number,
  minimum: number,
  maximum: number,
  name: string,
): number {
  const integer = positiveInteger(value, name);
  if (integer < minimum || integer > maximum) {
    throw new TypeError(`${name} must be between ${minimum} and ${maximum}`);
  }
  return integer;
}

async function readBoundedResponse(
  response: Response,
  maxBytes: number,
): Promise<string> {
  const contentLength = response.headers?.get?.('content-length');
  if (
    contentLength &&
    Number.isFinite(Number(contentLength)) &&
    Number(contentLength) > maxBytes
  ) {
    throw responseTooLarge(maxBytes);
  }

  const reader = response.body?.getReader?.();
  if (!reader) {
    const text = await response.text();
    if (new TextEncoder().encode(text).byteLength > maxBytes) {
      throw responseTooLarge(maxBytes);
    }
    return text;
  }

  const chunks: Uint8Array[] = [];
  let received = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      if (!value) continue;
      received += value.byteLength;
      if (received > maxBytes) {
        await reader.cancel();
        throw responseTooLarge(maxBytes);
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }
  const bytes = new Uint8Array(received);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return new TextDecoder().decode(bytes);
}

function invalidResponse(message: string): TableServiceError {
  return new TableServiceError({
    code: 'INVALID_RESPONSE',
    message,
    statusCode: 502,
    requestId: '',
  });
}

function responseTooLarge(maxBytes: number): TableServiceError {
  return new TableServiceError({
    code: 'RESPONSE_TOO_LARGE',
    message: `Table service response exceeds ${maxBytes} bytes`,
    statusCode: 413,
    requestId: '',
  });
}
