/** Machine-readable codes from docs/table-platform/contracts/errors.md */
export const TABLE_ERROR_CODES = [
  'UNAUTHORIZED',
  'FORBIDDEN',
  'DATASET_NOT_FOUND',
  'ROW_NOT_FOUND',
  'VALIDATION_ERROR',
  'SORT_NOT_PUSHED_DOWN',
  'FILTER_NOT_PUSHED_DOWN',
  'WRITE_NOT_SUPPORTED',
  'UNSUPPORTED_HYBRID',
  'SOURCE_RATE_LIMITED',
  'SOURCE_TIMEOUT',
  'AUTHORIZATION_UNAVAILABLE',
  'INVALID_RESPONSE',
  'RESPONSE_TOO_LARGE',
  'SYNC_IN_PROGRESS',
  'INTERNAL_ERROR',
] as const;

export type TableErrorCode = (typeof TABLE_ERROR_CODES)[number];

export class TableServiceError extends Error {
  readonly code: string;
  readonly statusCode: number;
  readonly requestId: string;
  readonly correlationURL?: string;

  constructor(input: {
    code: string;
    message: string;
    statusCode: number;
    requestId: string;
    correlationURL?: string;
  }) {
    super(input.message);
    this.name = 'TableServiceError';
    this.code = normalizeErrorCode(input.code);
    this.statusCode = input.statusCode;
    this.requestId = input.requestId;
    this.correlationURL = input.correlationURL;
  }
}

export function normalizeErrorCode(code: string): string {
  return code
    .trim()
    .replace(/[-\s]+/g, '_')
    .toUpperCase();
}

export function mapStatusToDefaultCode(status: number): TableErrorCode {
  switch (status) {
    case 401:
      return 'UNAUTHORIZED';
    case 403:
      return 'FORBIDDEN';
    case 404:
      return 'DATASET_NOT_FOUND';
    case 400:
      return 'VALIDATION_ERROR';
    case 409:
      return 'SYNC_IN_PROGRESS';
    case 422:
      return 'WRITE_NOT_SUPPORTED';
    case 429:
      return 'SOURCE_RATE_LIMITED';
    case 504:
      return 'SOURCE_TIMEOUT';
    case 503:
      return 'AUTHORIZATION_UNAVAILABLE';
    default:
      return 'INTERNAL_ERROR';
  }
}
